import { test, expect } from '@playwright/test';

test.describe('Sidebar Collapse/Expand Functionality', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/dashboard');
  });

  test('should collapse and expand sidebar on button click', async ({ page }) => {
    // Verify sidebar is initially expanded
    const sidebar = page.getByRole('navigation', { name: /sidebar/i });
    await expect(sidebar).toBeVisible();
    const menuItems = page.getByRole('link', { name: /menu item/i });
    await expect(menuItems).toHaveCount(5);

    // Get the collapse button using getByRole
    const collapseButton = page.getByRole('button', { name: /collapse sidebar/i });
    await expect(collapseButton).toBeVisible();

    // Click to collapse sidebar
    await collapseButton.click();

    // Verify sidebar is collapsed
    await expect(sidebar).toBeVisible();
    const collapsedWidth = 50;
    const currentWidth = await sidebar.evaluate((el) => el.offsetWidth);
    expect(currentWidth).toBeCloseTo(collapsedWidth);

    // Verify menu items are hidden or truncated
    const visibleMenuItems = page.getByRole('link', { name: /menu item/i });
    await expect(visibleMenuItems).toHaveCount(0);

    // Click to expand sidebar
    await collapseButton.click();

    // Verify sidebar is expanded again
    const expandedWidth = await sidebar.evaluate((el) => el.offsetWidth);
    expect(expandedWidth).toBeGreaterThan(collapsedWidth);

    // Verify menu items are visible
    await expect(visibleMenuItems).toHaveCount(5);
  });

  test('should handle multiple clicks and maintain state', async ({ page }) => {
    // Verify sidebar is initially expanded
    const sidebar = page.getByRole('navigation', { name: /sidebar/i });
    await expect(sidebar).toBeVisible();
    const menuItems = page.getByRole('link', { name: /menu item/i });
    await expect(menuItems).toHaveCount(5);

    // Click to collapse sidebar
    const collapseButton = page.getByRole('button', { name: /collapse sidebar/i });
    await collapseButton.click();

    // Verify sidebar is collapsed
    const collapsedWidth = await sidebar.evaluate((el) => el.offsetWidth);
    expect(collapsedWidth).toBeCloseTo(50);

    // Click again to expand sidebar
    await collapseButton.click();

    // Verify sidebar is expanded
    const expandedWidth = await sidebar.evaluate((el) => el.offsetWidth);
    expect(expandedWidth).toBeGreaterThan(collapsedWidth);

    // Click a third time to collapse again
    await collapseButton.click();

    // Verify sidebar is collapsed
    const finalCollapsedWidth = await sidebar.evaluate((el) => el.offsetWidth);
    expect(finalCollapsedWidth).toBeCloseTo(50);

    // Verify menu items are hidden
    const visibleMenuItems = page.getByRole('link', { name: /menu item/i });
    await expect(visibleMenuItems).toHaveCount(0);
  });
});
